import React, { useEffect, useMemo, useState } from 'react';
import { io } from 'socket.io-client';
import { useNavigate } from 'react-router-dom';
import { api, normalizeArrayPayload, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

function formatTime(ts) {
  if (!ts) return '—';
  try {
    return new Date(ts).toLocaleString();
  } catch {
    return ts;
  }
}

function parseArrayField(value) {
  if (Array.isArray(value)) return value;

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) return parsed;
    } catch (_) {}

    if (value.includes('->')) {
      return value.split('->').map((v) => v.trim()).filter(Boolean);
    }

    if (value.includes('→')) {
      return value.split('→').map((v) => v.trim()).filter(Boolean);
    }

    if (value.startsWith('{') && value.endsWith('}')) {
      return value
        .slice(1, -1)
        .split(',')
        .map((v) => v.trim())
        .filter(Boolean);
    }
  }

  return [];
}

function getLoopPath(item) {
  return (
    parseArrayField(item?.cycle) ||
    parseArrayField(item?.cycle_path) ||
    parseArrayField(item?.loop_path) ||
    parseArrayField(item?.path) ||
    []
  );
}

function getTradePath(item) {
  return (
    parseArrayField(item?.trade_path) ||
    parseArrayField(item?.trade_ids) ||
    parseArrayField(item?.transactions) ||
    []
  );
}

function getTradeId(item) {
  return item?.trade_id ?? item?.root_trade_id ?? item?.id ?? '—';
}

function getStock(item) {
  return item?.symbol ?? item?.stock_symbol ?? item?.stock_id ?? '—';
}

function getDepth(item, loopPath, tradePath) {
  if (item?.depth != null) return item.depth;
  if (tradePath.length) return tradePath.length;
  if (loopPath.length) return Math.max(0, loopPath.length - 1);
  return '—';
}

function getConfidence(item, loopPath) {
  if (item?.confidence != null) return item.confidence;
  if (loopPath.length >= 6) return 95;
  if (loopPath.length === 5) return 90;
  if (loopPath.length === 4) return 85;
  if (loopPath.length === 3) return 75;
  return 0;
}

function scoreBadgeClass(score) {
  const val = Number(score || 0);
  if (val >= 70) return 'badge badge-high';
  if (val >= 40) return 'badge badge-medium';
  return 'badge badge-low';
}

function FraudAlertToast({ alert, onClose }) {
  if (!alert) return null;

  const loopPath = getLoopPath(alert);

  return (
    <div
      style={{
        position: 'fixed',
        top: 88,
        right: 24,
        width: 360,
        zIndex: 1000,
        background: 'linear-gradient(180deg, rgba(45,10,10,0.96), rgba(28,7,7,0.96))',
        border: '1px solid rgba(255,90,90,0.28)',
        borderRadius: 18,
        padding: 18,
        boxShadow: '0 18px 50px rgba(0,0,0,0.45)',
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 10 }}>
        <div style={{ display: 'flex', gap: 12 }}>
          <div
            style={{
              width: 16,
              height: 16,
              borderRadius: 999,
              background: '#ff5e73',
              boxShadow: '0 0 20px rgba(255,94,115,0.7)',
              marginTop: 3,
              flexShrink: 0,
            }}
          />
          <div>
            <div style={{ color: '#fff', fontSize: 16, fontWeight: 900 }}>
              Circular Trade Alert
            </div>
            <div style={{ color: '#ffb7b7', fontSize: 14, lineHeight: 1.4, marginTop: 6 }}>
              {loopPath.length ? `Loop: ${loopPath.join(' → ')}` : 'Circular loop detected'}
            </div>
            <div style={{ color: '#b79595', fontSize: 12, marginTop: 8 }}>
              Trade #{getTradeId(alert)} • Risk {alert?.risk_score ?? '—'}
            </div>
          </div>
        </div>

        <button
          onClick={onClose}
          style={{
            background: 'transparent',
            border: 0,
            color: '#b28d8d',
            cursor: 'pointer',
            fontSize: 20,
            lineHeight: 1,
          }}
        >
          ×
        </button>
      </div>
    </div>
  );
}

function StatCard({ label, value, color }) {
  return (
    <div className="glass-strong card-hover" style={{ padding: 22 }}>
      <div
        style={{
          color: '#808779',
          fontSize: 12,
          fontWeight: 800,
          letterSpacing: '0.08em',
          textTransform: 'uppercase',
          marginBottom: 14,
        }}
      >
        {label}
      </div>
      <div style={{ fontSize: 42, fontWeight: 900, color, marginBottom: 6 }}>{value}</div>
    </div>
  );
}

export default function FraudPage() {
  const navigate = useNavigate();

  const [stats, setStats] = useState({});
  const [fraudCycles, setFraudCycles] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [activeTab, setActiveTab] = useState('cycles');
  const [toast, setToast] = useState(null);

  const loadAll = async () => {
    try {
      const [statsRes, cyclesRes, logsRes] = await Promise.all([
        api.fetchStats(),
        api.fetchFraudCycles(),
        api.fetchRiskLogs(),
      ]);

      const rawCycles = normalizeArrayPayload(cyclesRes);
      const rawLogs = normalizeArrayPayload(logsRes);

      const normalizedCycles = rawCycles
        .map((item) => {
          const loopPath = getLoopPath(item);
          const tradePath = getTradePath(item);

          return {
            original: item,
            trade_id: getTradeId(item),
            stock: getStock(item),
            loopPath,
            tradePath,
            depth: getDepth(item, loopPath, tradePath),
            confidence: getConfidence(item, loopPath),
          };
        })
        .filter((item) => item.loopPath.length >= 3);

      setStats(statsRes || {});
      setFraudCycles(normalizedCycles);
      setRiskLogs(rawLogs);
    } catch (error) {
      console.error('FraudPage load error:', error);
    }
  };

  useEffect(() => {
    loadAll();

    const intervalId = setInterval(loadAll, 2500);
    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });

    socket.on('fraud_detected', (payload) => {
      loadAll();
      const loopPath = getLoopPath(payload);
      if (loopPath.length >= 3) {
        setToast(payload);
      }
    });

    socket.on('fraud_alert', (payload) => {
      loadAll();
      const loopPath = getLoopPath(payload);
      if (loopPath.length >= 3) {
        setToast(payload);
      }
    });

    socket.on('risk_log', loadAll);
    socket.on('trade_inserted', loadAll);

    return () => {
      clearInterval(intervalId);
      socket.disconnect();
    };
  }, []);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 5000);
    return () => clearTimeout(t);
  }, [toast]);

  const criticalCount = useMemo(
    () => riskLogs.filter((r) => Number(r.risk_score || 0) >= 70).length,
    [riskLogs]
  );

  return (
    <div className="page-wrap grid-bg">
      <FraudAlertToast alert={toast} onClose={() => setToast(null)} />

      <div className="page-container">
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            gap: 20,
            alignItems: 'flex-start',
            marginBottom: 18,
          }}
        >
          <div>
            <h1 style={{ fontSize: 28, fontWeight: 900, margin: 0 }}>
              Fraud <span className="neon-strong">Engine</span>
            </h1>
            <div style={{ color: '#858d80', marginTop: 10, fontSize: 14 }}>
              WITH RECURSIVE SQL engine scanning all trade cycles in real time
            </div>
          </div>

          <button className="btn-primary" onClick={() => navigate('/dashboard')}>
            Launch Dashboard
          </button>
        </div>

        <div className="kpi-grid" style={{ marginBottom: 18 }}>
          <StatCard
            label="Total Cycles"
            value={fraudCycles.length}
            color={fraudCycles.length > 0 ? '#ff6262' : '#ff7d7d'}
          />
          <StatCard
            label="Critical (≥70)"
            value={criticalCount}
            color={criticalCount > 0 ? '#ff6262' : '#ffb020'}
          />
          <StatCard
            label="Risk Log Entries"
            value={riskLogs.length}
            color="#ffbf38"
          />
        </div>

        <div style={{ display: 'flex', gap: 12, marginBottom: 16 }}>
          <button
            onClick={() => setActiveTab('cycles')}
            className={activeTab === 'cycles' ? 'btn-primary' : 'btn-outline'}
          >
            Fraud Cycles ({fraudCycles.length})
          </button>

          <button
            onClick={() => setActiveTab('logs')}
            className={activeTab === 'logs' ? 'btn-primary' : 'btn-outline'}
          >
            Risk Logs ({riskLogs.length})
          </button>
        </div>

        {activeTab === 'cycles' ? (
          <div className="glass-strong" style={{ overflow: 'hidden' }}>
            <div
              style={{
                padding: '18px 20px',
                borderBottom: '1px solid rgba(255,255,255,0.05)',
              }}
            >
              <div style={{ fontSize: 18, fontWeight: 900 }}>Detected Circular Loops</div>
              <div style={{ color: '#808879', fontSize: 13, marginTop: 6 }}>
                Main focus: exact circular trader path and linked trade path
              </div>
            </div>

            <div className="scroll-y" style={{ maxHeight: 560 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Trade ID</th>
                    <th>Stock</th>
                    <th>Loop Path</th>
                    <th>Trade Path</th>
                    <th>Depth</th>
                    <th>Confidence</th>
                  </tr>
                </thead>
                <tbody>
                  {fraudCycles.map((item, idx) => (
                    <tr key={`${item.trade_id}-${idx}`}>
                      <td>#{item.trade_id}</td>
                      <td>{item.stock}</td>
                      <td style={{ color: '#ff7070', fontWeight: 800 }}>
                        {item.loopPath.length ? item.loopPath.join(' → ') : '—'}
                      </td>
                      <td style={{ color: '#a3b09d' }}>
                        {item.tradePath.length ? item.tradePath.join(' → ') : '—'}
                      </td>
                      <td>{item.depth}</td>
                      <td>
                        <span className={scoreBadgeClass(item.confidence)}>
                          {item.confidence}
                        </span>
                      </td>
                    </tr>
                  ))}

                  {!fraudCycles.length && (
                    <tr>
                      <td colSpan="6">
                        <div className="empty-state">
                          No circular loops detected yet. This section will show paths like
                          12 → 19 → 27 → 12 when a trading ring is found.
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <div className="glass-strong" style={{ overflow: 'hidden' }}>
            <div
              style={{
                padding: '18px 20px',
                borderBottom: '1px solid rgba(255,255,255,0.05)',
              }}
            >
              <div style={{ fontSize: 18, fontWeight: 900 }}>Risk Logs</div>
              <div style={{ color: '#808879', fontSize: 13, marginTop: 6 }}>
                Supporting suspicious signals: cycle risk, trust issues, repeated trades, price anomalies
              </div>
            </div>

            <div className="scroll-y" style={{ maxHeight: 560 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Trade ID</th>
                    <th>Risk Score</th>
                    <th>Label</th>
                    <th>Reason</th>
                    <th>Detected</th>
                  </tr>
                </thead>
                <tbody>
                  {riskLogs.map((log, idx) => (
                    <tr key={`${log.risk_id || log.trade_id}-${idx}`}>
                      <td>#{log.trade_id}</td>
                      <td>{log.risk_score}</td>
                      <td>
                        <span className={badgeClass(log.risk_score)}>
                          {Number(log.risk_score || 0) >= 70
                            ? 'HIGH'
                            : Number(log.risk_score || 0) >= 40
                            ? 'MEDIUM'
                            : 'LOW'}
                        </span>
                      </td>
                      <td style={{ maxWidth: 520 }}>{log.reason}</td>
                      <td>{formatTime(log.detected_at)}</td>
                    </tr>
                  ))}

                  {!riskLogs.length && (
                    <tr>
                      <td colSpan="5">
                        <div className="empty-state">No risk logs yet.</div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
